#!/usr/bin/env bash
# Applies שמרתי's customizations to the Android project generated by `npx cap add android`.
set -euo pipefail

RUN="${GITHUB_RUN_NUMBER:-1}"
VERSION="${APP_VERSION:-1.0}"
APP=android/app
RES=$APP/src/main/res
MAN=$APP/src/main/AndroidManifest.xml

# 1) Icons and splash
find "$RES" -name 'splash.png' -delete
cp -R android-res/. "$RES/"

# 2) App name in Hebrew (the label under the icon)
STR=$RES/values/strings.xml
perl -0pi -e 's|<string name="app_name">[^<]*</string>|<string name="app_name">שמרתי</string>|; s|<string name="title_activity_main">[^<]*</string>|<string name="title_activity_main">שמרתי</string>|' "$STR"

# 3) "Share → שמרתי": appear in Android's share menu for links and text (TikTok, Instagram, YouTube, any browser)
perl -0pi -e 's|(</intent-filter>)|$1\n\n            <intent-filter>\n                <action android:name="android.intent.action.SEND" />\n                <category android:name="android.intent.category.DEFAULT" />\n                <data android:mimeType="text/plain" />\n            </intent-filter>|' "$MAN"
perl -0pi -e 's|</manifest>|    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />\n    <uses-permission android:name="android.permission.VIBRATE" />\n</manifest>|' "$MAN"

# 4) A shared link arrives as ACTION_SEND text. MainActivity turns it into shamarti://share?text=…
#    so the web app receives it through the App plugin (launch URL / appUrlOpen), with no extra plugin.
MAIN=$(find "$APP/src/main/java" -name MainActivity.java | head -1)
PKG=$(sed -n 's/^package \(.*\);/\1/p' "$MAIN")
cat > "$MAIN" <<JAVA
package ${PKG};

import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
    @Override
    public void onCreate(Bundle savedInstanceState) {
        Intent shared = shareToView(getIntent());
        if (shared != null) setIntent(shared);
        super.onCreate(savedInstanceState);
    }

    @Override
    public void onNewIntent(Intent intent) {
        Intent shared = shareToView(intent);
        if (shared != null) {
            setIntent(shared);
            super.onNewIntent(shared);
        } else {
            super.onNewIntent(intent);
        }
    }

    private static Intent shareToView(Intent in) {
        if (in == null || !Intent.ACTION_SEND.equals(in.getAction())) return null;
        CharSequence text = in.getCharSequenceExtra(Intent.EXTRA_TEXT);
        String subject = in.getStringExtra(Intent.EXTRA_SUBJECT);
        Uri.Builder b = new Uri.Builder().scheme("shamarti").authority("share")
            .appendQueryParameter("text", text == null ? "" : text.toString())
            .appendQueryParameter("t", String.valueOf(System.currentTimeMillis()));
        if (subject != null) b.appendQueryParameter("subject", subject);
        Intent out = new Intent(Intent.ACTION_VIEW, b.build());
        return out;
    }
}
JAVA

# 5) Red splash with the bookmark on Android 12+
STY=$RES/values/styles.xml
perl -0pi -e 's|(<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">)|$1\n        <item name="windowSplashScreenBackground">#D9381E</item>\n        <item name="windowSplashScreenAnimatedIcon">\@mipmap/ic_launcher_foreground</item>|' "$STY"

# 6) Target SDK 34 (classic status bar; the app is installed directly, not from Play)
sed -i -E 's/targetSdkVersion = [0-9]+/targetSdkVersion = 34/' android/variables.gradle

# 7) Version: name is the product version, code is the build number (so every APK installs as an update)
sed -i -E "s/versionCode [0-9]+/versionCode ${RUN}/; s/versionName \"[^\"]*\"/versionName \"${VERSION}\"/" "$APP/build.gradle"

# 8) Release signing with the permanent key (password from GitHub secrets)
cat >> "$APP/build.gradle" <<'GRADLE'

android {
    signingConfigs {
        shamarti {
            storeFile file("release.jks")
            storePassword System.getenv("SHAMARTI_STORE_PASSWORD")
            keyAlias System.getenv("SHAMARTI_KEY_ALIAS")
            keyPassword System.getenv("SHAMARTI_KEY_PASSWORD")
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.shamarti
            minifyEnabled false
        }
    }
}
GRADLE

echo "--- manifest"; grep -n 'intent\|action\|category\|data \|uses-permission\|launchMode' "$MAN"
echo "--- strings"; cat "$STR"
echo "--- main activity ($PKG)"; head -5 "$MAIN"
echo "--- launch style"; grep -n -A3 'NoActionBarLaunch' "$STY"
echo "--- versions"; grep -n -E 'versionCode|versionName' "$APP/build.gradle"; grep -n targetSdk android/variables.gradle
